static inline struct nlmsghdr *nlmsg_put(struct sk_buff *skb, u32 portid, u32 seq, /* <=== nlmsg_put */ 
					 int type, int payload, int flags)
{
	if (unlikely(skb_tailroom(skb) < nlmsg_total_size(payload)))
		return NULL;

	return __nlmsg_put(skb, portid, seq, type, payload, flags);
}

static inline int atomic_read(const atomic_t *v) /* <=== atomic_read */ 
{
	return ACCESS_ONCE((v)->counter);
}

static inline int atomic_read(const atomic_t *v) /* <=== atomic_read */ 
{
	return READ_ONCE((v)->counter);
}

static inline void module_put(struct module *module) /* <=== module_put */ 
{
}

static inline struct netlink_sock *nlk_sk(struct sock *sk) /* <=== nlk_sk */ 
{
	return container_of(sk, struct netlink_sock, sk);
}

static inline int atomic_read(const atomic_t *v) /* <=== atomic_read */ 
{
	return ACCESS_ONCE((v)->counter);
}

struct nlmsghdr * /* <=== __nlmsg_put */ 
__nlmsg_put(struct sk_buff *skb, u32 portid, u32 seq, int type, int len, int flags)
{
	struct nlmsghdr *nlh;
	int size = nlmsg_msg_size(len);

	nlh = (struct nlmsghdr *)skb_put(skb, NLMSG_ALIGN(size));
	nlh->nlmsg_type = type;
	nlh->nlmsg_len = size;
	nlh->nlmsg_flags = flags;
	nlh->nlmsg_pid = portid;
	nlh->nlmsg_seq = seq;
	if (!__builtin_constant_p(size) || NLMSG_ALIGN(size) - size != 0)
		memset(nlmsg_data(nlh) + len, 0, NLMSG_ALIGN(size) - size);
	return nlh;
}

static inline int nlmsg_total_size(int payload) /* <=== nlmsg_total_size */ 
{
	return NLMSG_ALIGN(nlmsg_msg_size(payload));
}

static inline struct nlmsghdr *nlmsg_put_answer(struct sk_buff *skb, /* <=== nlmsg_put_answer */ 
						struct netlink_callback *cb,
						int type, int payload,
						int flags)
{
	return nlmsg_put(skb, NETLINK_CB(cb->skb).portid, cb->nlh->nlmsg_seq,
			 type, payload, flags);
}

static inline int atomic_read(const atomic_t *v) /* <=== atomic_read */ 
{
	return READ_ONCE(v->counter);
}

